ns.News = { builtAt = "2026-09-15", cards = { { i = "INV_Misc_PocketWatch_01", t = "《无限》开服时间", tEn = "Forever launch", d = "国服 Beta 10/06 已开 · 全球上线 11/04 · 国服上线 11/05 · 首批团本 12/10", dEn = "Global Beta 09-17 · China Beta 10-06 · Global launch 11-04 · China launch 11-05 · First raids unlock 12-10", launch = "2026-11-05" }, { i = "INV_Misc_Key_03", t = "新内容", tEn = "What's new", d = "60 级封顶 · 永远不涨；9 新地下城；2 新团本 · 10 人 / 20 人；4 新区域 + 1 新战场；1000+ 新任务 · 铺满 1–60；600+ 新配方", dEn = "60 level cap, forever; 9 new dungeons; 2 new raids (10 / 20); 4 new zones + 1 battleground; 1000+ new quests, 1–60; 600+ new recipes" }, { i = "Ability_Mount_Gryphon_01", t = "没有飞行坐骑", tEn = "No flying mounts", d = "设计原则，不是「以后再加」。", dEn = "A design principle, not \"later\"." }, { i = "Spell_Holy_Restoration", t = "没有等级同步", tEn = "No level scaling", d = "低级区永远是低级区，40 级的野怪不会跟着你涨。", dEn = "Low-level zones stay low-level; a level-40 mob never scales to you." }, { i = "INV_Misc_Book_08", t = "60 级永远封顶", tEn = "Level 60 cap, forever", d = "专业一直值钱，装备一直值钱；追赶系统就是去玩游戏。", dEn = "Professions stay valuable, gear stays valuable; the catch-up system is playing the game." }, { i = "INV_Misc_Map_01", t = "没有服务器，四种规则集", tEn = "No servers — four rulesets", d = "普通 / PvP / RP / 硬核。硬核 11 月首发没有，之后再加；死了不删号，可转其他规则集，进度只出不进。", dEn = "Normal / PvP / RP / Hardcore. Hardcore is not in the November launch; it comes later. Death doesn't delete: transfer to another ruleset, progress moves one way only." } }, releases = { { v = "0.7.3", date = "2026-11-07", zh = "位面：修复部分地方认不出层（显示「?」）；换层求助冷却 3 分钟改 1 分钟", en = "Layers: fixed '?' where the game only reports the continent; request cooldown 3 min -> 1 min" }, { v = "0.7.2", date = "2026-11-07", zh = "所有专精都有升级加点了（新增生存 / 射击 / 狂怒 / 刺杀 / 敏锐 / 戒律 / 元素 / 火焰 / 恶魔学识 / 毁灭）；位面修复假层、提示谁拉的你；屏蔽播报覆盖入会欢迎并改为默认关", en = "Leveling builds for every spec (10 new); layers: fake-layer fix and who pulled you; shout filter covers guild welcomes and is now off by default" }, { v = "0.7.1", date = "2026-11-07", zh = "位面：修复「没开帮忙」误显示、别的图会员也能拉你、请帮得最少的人、总开关；睡袋任务线全程追踪小窗 + 第 6 步实录视频；播报名字带姓、修复弹框发不出去", en = "Layers: fixed the 'not helping' display, other-map guildmates can pull you, asks the least-busy helper, master switch; sleeping bag tracker window + step 6 video; shouts include surnames, popup send fixed" }, { v = "0.7.0", date = "2026-11-07", zh = "新增「位面」：认出你在第几层，会员互相拉一下就能换层；野外击杀 / 被杀弹框播报（带坐标和地图标记）；升级逢 5 级自动发、其他级弹框问；公会招募板重做；睡袋石爪山地图标记修正", en = "New Layers tab: see your layer and get guildmates to pull you to another; world PvP kill / death popups with coordinates and map pin; level-up shout auto every 5 levels, asks on others; recruiting board redesigned; Stonetalon sleeping bag pin fixed" }, { v = "0.6.3", date = "2026-11-06", zh = "法师奥术组队刷本加点；猎人宠物「在哪抓」加野兽头像和玩家实测数据（≥2 人一致才采信）；公会频道等级标签可显示地区；设置页新开关并可滚动", en = "Mage Arcane group-leveling build; hunter pet \"where to tame\" adds beast portraits and player-reported data (trusted after 2+ players agree); guild chat level tags can show the zone; new settings toggles and a scrolling settings page" }, { v = "0.6.2", date = "2026-11-06", zh = "小地图按钮修复：贴在小地图边上（新版小地图上原来缩在图里）、兼容收纳插件和信息条、小地图「插件」总按钮里也能点开", en = "Minimap button fixed: sits on the minimap edge (it used to sit inside the larger new minimap), works with button-collector and data-broker addons, and can be opened from the minimap addon compartment" }, { v = "0.6.1", date = "2026-11-06", zh = "角色面板当前等级 BiS 角标（点击看获取方式）；BiS 推荐加入商人件，制造件作为「也可以」备选；猎人宠物「在哪抓」；右键菜单「邀请入会」；组队工具组的队自动自由拾取；主动退队也弹感谢框", en = "Current-level BiS corner icons on the character panel (click for where to get it); BiS picks now include vendor items, crafted items shown as alternatives; hunter pet \"where to tame\"; right-click \"Invite to guild\"; groups formed with the quest-mates tool switch to free-for-all loot; thanks popup also when you leave the group yourself" }, { v = "0.6.0", date = "2026-11-06", zh = "天赋树按开服客户端重做、配点码升级 GIF2；键位 / 速查 / 宏 / 技能 / 物品数据更新到开服版本；睡袋任务线逐步详情；公会招募列表恢复刷新", en = "Talent trees rebuilt from the launch client, talent codes now GIF2; keybinds / cheat sheet / macros / spells / items updated to launch; detailed sleeping bag quest line; guild recruiting list refresh fixed" }, { v = "0.5.11", date = "2026-11-05", zh = "组队「同任务的人」改走公会频道 + 静默密语（自建频道在《无限》里发不出去）；公会频道消息前显示说话人等级；采集点众包；战绩卡二维码下线", en = "Quest mates now share via guild chat and silent addon whispers (custom channels don't work in Forever); guild chat shows the speaker's level; gathering-node crowdsourcing; beta card QR removed" }, { v = "0.5.10", date = "2026-11-05", zh = "修复组队「同任务的人」发送失败（显示原因、自动重进频道）、天赋推荐跟着投点的系走、键位页分组修正并去掉被动；升级播报加本职业排名；公会招募页改大卡 + 职业图标", en = "Fixes quest-mate sharing failures (shows the reason, rejoins the channel), talent picks follow your main tree, Keys page groups fixed and passives removed; level-up shouts add your class rank; guild recruitment page uses full-size cards and class icons" }, { v = "0.5.9", date = "2026-11-04", zh = "修复：资讯页的微信群二维码换成新码（原码已过期）", en = "Fix: the WeChat group QR code on the News page is replaced with a new one (the old one had expired)" }, { v = "0.5.8", date = "2026-11-04", zh = "升级规划新增「副本任务」页签；副本任务窗口加入口路线与官方指南补充（入口按官方指南更新，敌对领地会提示）", en = "Leveling plan gets a Dungeon quests view; the dungeon quest window adds entrance routes and official-guide additions (entrances updated from the official guide, hostile-territory warnings)" }, { v = "0.5.7", date = "2026-10-29", zh = "推荐装备只推《无限》里拿得到的（去掉经典团本装）；武器战 / 惩戒骑有双手武器时副手留空；采集草药的观测修正", en = "Gear picks now only suggest items you can actually get in Forever (classic raid gear removed); Arms Warriors and Retribution Paladins with a two-hander leave the off-hand empty; herb-gathering observation fixed" }, { v = "0.5.6", date = "2026-10-26", zh = "新增：屏蔽别人的升级播报（默认开，设置页「公会」栏 / /gi 屏蔽升级 开|关）；本插件的升级播报默认改为只在 10·20·…·60 级发", en = "New: hide other players' level-up shouts (on by default; Settings > Guild or /gi lvlmute on|off); our own level-up shout now defaults to milestones only (10, 20 ... 60)" }, { v = "0.5.5", date = "2026-10-25", zh = "修复：聊天时不停弹「attempted to iterate a table that cannot be accessed while tainted」报错（公会频道等级显示改动了暴雪聊天框，先暂停这个显示）；推荐装备页签图标修正", en = "Fix: the repeating \"attempted to iterate a table that cannot be accessed while tainted\" error while chatting (guild chat level display modified the Blizzard chat frames and is paused for now); Gear picks tab icon fixed" }, { v = "0.5.4", date = "2026-10-22", zh = "数据跟上公测客户端：天赋页 / 默认加点按最新天赋重做，专业 / 营地 / 宠物 / 成就数据更新；营火写清学会和放下两个门槛；新手区初级训练师进升级规划；更新器匿名收集训练师、采集需求等游戏内信息补全数据", en = "Data updated to the launch client: talents and default builds refreshed, professions / camping / pets / achievements updated; campfires show learn and place skill; starting-zone junior trainers in the leveling plan; the updater anonymously collects in-game trainer and gathering info to fill data gaps" }, { v = "0.5.3", date = "2026-10-21", zh = "新增「共建」页签（看正在做 / 待排期 / 最近交付，一键复制报 BUG / 提需求链接，/gi bug）；开商人窗口和拾取时自动记下图纸出处", en = "New Build-together tab (in progress / queued / shipped, copy bug-report and request links, /gi bug); recipe sources are recorded from vendor windows and loot" }, { v = "0.5.2", date = "2026-10-21", zh = "配方库写上图纸出处（商人坐标 / 商人青睐 / 掉落 / 任务 / 声望），可按出处筛选、搜商人和地区；修正微信群二维码", en = "Recipes show where to get them (vendors with coordinates, Merchant's Favor, drops, quests, reputation) with a source filter; WeChat group QR fixed" }, { v = "0.4.31", date = "2026-10-14", zh = "任务组队优先匹配，200人缓存与20人临时接收；修复满缓存漏人和任务进度读取，私聊显示小队人数", en = "Quest grouping prioritizes matching players with a 200-peer cache and 20 staging slots; fixes cache lockout and quest progress parsing; whispers include party size" }, { v = "0.4.29", date = "2026-10-13", zh = "地图待办合并练级区域与升级事项；附近组队筛选更清楚，修复喊人冷却时右键切换，收紧人数和刷新开销", en = "Unified leveling zones and tasks; clearer nearby quest filters, right-click channel switching during cooldown, and bounded peer/render costs" }, { v = "0.4.28", date = "2026-10-12", zh = "附近同任务组队、升级路线、键位与手法提示、资讯页支持榜", en = "Nearby quest grouping, leveling routes, keybind and rotation helpers, and support information" }, { v = "0.4.27", date = "2026-10-12", zh = "主面板右侧新增「公会」页签：装了 GuildInsight 一键打开招募页，没装也能看正在招人的公会", en = "New Guild tab on the right of the main window: opens GuildInsight's Recruit page, or lists guilds that are recruiting" }, { v = "0.4.26", date = "2026-10-11", zh = "野外稀有补上《无限》新掉落（卡利姆多的祝福三件蓝装等），108 只稀有按实际刷新点重新定位地区和坐标", en = "World rares now list Forever's new drops (Blessing of Kalimdor blues and more); 108 rares relocated to their real spawn zones" }, { v = "0.4.25", date = "2026-10-11", zh = "掉落页参考掉率、精英与稀有、248 个野外稀有带坐标；天赋推荐方案可切换；新页签「成就 · 传承」", en = "Drop rates, elites & rares, 248 world rares with coordinates; switchable talent builds; new Achievements tab" }, { v = "0.4.24", date = "2026-10-11", zh = "副本任务：29 个副本 380+ 个任务；首领头像与加载画面横幅；宏库新增「通用 · 系统宏」", en = "Dungeon quests: 29 dungeons, 380+ quests; boss portraits and loading-screen banners; new General · System macros" }, { v = "0.2.0", date = "2026-10-07", zh = "主界面改版：图标页签、天赋模拟器、宏库 197 条一键导入、掉落心愿单、T1 套装、资讯；命令改成 /gi", en = "New main window: icon tabs, talent simulator, 197 one-click macros, loot wishlist, Tier 1 sets, news; command is now /gi" } }, channels_cn = { { "网站", "gearinsight.cn", "gearinsight.cn/wow/forever", "web" }, { "公众号", "gear魔兽装备", "微信搜「gear魔兽装备」", "wechat" }, { "微信小程序", "GearInsight", "微信搜「GearInsight」小程序：BiS / 掉落 / 天赋 / 万奥宝典，手机随时查", "mp" }, { "抖音", "魔兽装备管家·GearInsight", "抖音搜「GearInsight」", "douyin" }, { "小红书", "GearInsight", "小红书搜「GearInsight」", "xhs" }, { "B站", "GearInsight", "B站搜「GearInsight」", "bili" }, { "QQ群", "152706590", "152706590", "qq" } }, channels_en = { { "Website", "gearinsight.app", "gearinsight.app/wow/forever", "web" }, { "X", "@GearInsightApp", "x.com/GearInsightApp", "x" }, { "YouTube", "@GearInsightWoW", "youtube.com/@GearInsightWoW", "youtube" }, { "Telegram", "t.me/gearInsight", "t.me/gearInsight", "tg" } }, wx = { name = "无限服-GI插件群", expires = "2026-11-16", n = 41, rows = { "11111110111110011100001001110000001